('enchiladas-suizas-suaves-mexico', 'Enchiladas suizas suaves', 'Enchiladas mexicanas suizas en versión baby: tortillas con pollo desmenuzado, bañadas en salsa de tomate verde con crema y queso gratinado. SIN chile.', ARRAY['almuerzo','cena'], ARRAY['preescolar'], 35, 3, ARRAY['gluten','lactosa']::text[], 290, 18, 30, 11, 1.8,
'[{"id":"tortillas","nombre":"Tortillas de maíz","cantidad":4,"unidad":"unidades","calorias_por_100g":218},{"id":"pollo","nombre":"Pechuga de pollo cocida desmenuzada","cantidad":120,"unidad":"g","calorias_por_100g":165},{"id":"tomate-verde","nombre":"Tomate verde (tomatillo)","cantidad":150,"unidad":"g","calorias_por_100g":32},{"id":"cebolla","nombre":"Cebolla","cantidad":40,"unidad":"g","calorias_por_100g":40},{"id":"crema","nombre":"Crema fresca","cantidad":50,"unidad":"ml","calorias_por_100g":340},{"id":"queso","nombre":"Queso para gratinar","cantidad":50,"unidad":"g","calorias_por_100g":264},{"id":"cilantro","nombre":"Cilantro","cantidad":3,"unidad":"hojas","calorias_por_100g":23}]'::jsonb,
'[{"orden":1,"descripcion":"Hierve los tomatillos con la cebolla durante 8 minutos hasta que estén blandos.","duracion_min":10},{"orden":2,"descripcion":"Licúa los tomatillos con cilantro hasta obtener salsa verde lisa y mezcla con la crema.","duracion_min":3},{"orden":3,"descripcion":"Calienta las tortillas, rellena cada una con pollo desmenuzado y enrolla.","duracion_min":6},{"orden":4,"descripcion":"Coloca las enchiladas en fuente, baña con la salsa verde-crema y queso encima. Hornea 15 min a 180°C.","duracion_min":18}]'::jsonb,
ARRAY['mexico','latam','enchiladas','suizas','iconico','sin-chile','horneado','pollo'], false, true)
ON CONFLICT (slug) DO NOTHING;

