'[{"orden":1,"descripcion":"Hierve el pollo con cebolla y ajo en el agua durante 25 minutos.","duracion_min":25},{"orden":2,"descripcion":"Retira el pollo, desmenúzalo y devuelve el caldo a la olla.","duracion_min":4},{"orden":3,"descripcion":"Agrega el maíz pozolero ya cocido y el pollo desmenuzado, cocina 12 minutos más.","duracion_min":12},{"orden":4,"descripcion":"Sirve con lechuga picada fina, rabanitos rebanados y unas gotas de limón al gusto.","duracion_min":5}]'::jsonb,
