('pan-muerto-baby-light-mexico', 'Pan de muerto baby light', 'Versión light del icónico pan de muerto mexicano: pan dulce con aroma a azahar y naranja, MUY poca azúcar.', ARRAY['snack','desayuno'], ARRAY['preescolar'], 90, 6, ARRAY['gluten','huevo','lactosa']::text[], 235, 7, 38, 6, 1.5,
